from contextlib import contextmanager
from typing import TYPE_CHECKING, Optional
from taf.ul.sbts.energy_saving.decorators.connection import with_connection
from taf.ul.sbts.energy_saving.exceptions import DeltaError

if TYPE_CHECKING:
    from taf.ul.sbts.energy_saving.core.context import EnergySavingContext


class DeltaManager:
    """Delta operations manager"""

    def __init__(self, context: 'EnergySavingContext'):
        self.context = context

    def create_delta(self, delta_id: int = 0):
        """Create delta"""
        return self.context.admin.create_delta(delta_id=delta_id)

    def remove_delta(self, delta_id: int = 0):
        """Remove delta"""
        return self.context.admin.remove_delta(delta_id=delta_id)

    def get_delta(self, delta_id: int = 0):
        """Get delta"""
        return self.context.admin.get_delta(delta_id=delta_id)

    @with_connection
    def perform_delta_recommissioning(self, delta, activate: bool = False, connection=None):
        """Perform delta recommissioning"""
        return self.context.admin.perform_delta_recommissioning(delta, connection=connection, should_activate=activate)

    @contextmanager
    def delta_context(self, delta_id: int = 0, auto_commit: bool = True, connection_alias: Optional[str] = None):
        """Context manager for delta operations"""
        try:
            self.create_delta(delta_id)
            yield delta_id
            if auto_commit:
                delta = self.get_delta(delta_id)
                self.perform_delta_recommissioning(delta, activate=True, connection_alias=connection_alias)
        except Exception as e:
            raise DeltaError(f"Delta operation failed: {e}") from e
        finally:
            self.remove_delta(delta_id)

    def append_managed_object_to_delta(self, dist_name: str, operation: str = "create", delta_id: int = 0):
        """Add managed object operation to delta"""
        return self.context.admin.append_managed_object_to_delta(dist_name, operation, delta_id)

    def append_parameter_update_to_delta(self, dist_name: str, parameter: str, value, delta_id: int = 0):
        """Add parameter update to delta"""
        return self.context.admin.append_parameter_update_to_delta(dist_name=dist_name, parameter=parameter,
                                                                   value=value, delta_id=delta_id)

    def delete_managed_objects(self, dist_names: list, delta_id: int = 0):
        """Delete multiple managed objects"""
        with self.delta_context(delta_id, auto_commit=True) as delta_id:
            for dn in dist_names:
                self.append_managed_object_to_delta(dn, operation="delete", delta_id=delta_id)

    def append_complex_item_to_delta(self, dist_name: str, list_name: str, delta_id: int = 0, **kwargs):
        """Add complex item to delta"""
        return self.context.admin.append_complex_item_to_delta(dist_name, list_name=list_name, delta_id=delta_id,
                                                               **kwargs)

    def __repr__(self):
        return f"DeltaManager(context={self.context.connection_alias})"
